//! Mobile numbers and SMS verification codes: sending codes and limits, verification, SMS login and registration,
//! binding, rebinding and unbinding, and setting a password for accounts without one.
//!
//! - Only mainland China +86 11-digit mobile numbers are accepted, stored as E.164 (`+8613800000000`) and displayed
//!   masked (`138****0000`).
//! - Codes are 6 digits generated by this site; the database only stores a digest: HMAC-SHA256 of number, purpose,
//!   issue time and code, under a key derived from the cookie key. Six digits are only 10^6 values and the other
//!   inputs sit in the same row, so without a secret from the private configuration anyone holding the code table
//!   could recover a code offline. The cookie keys in `previous_keys` keep codes sent before a rotation valid;
//!   codes sent under a removed key no longer verify. Verification only accepts the newest row for the same number
//!   and purpose that was delivered (a code the provider did not take leaves the previous one current), wrong
//!   attempts are counted in the database, and the code is voided at the limit. The provider only delivers
//!   ([`crate::sms`]).
//! - Limits: the interval per number, per number per day and site-wide per day are counted in the database (days split
//!   by the site time zone); per IP per hour is handled by the rate limiter in the router layer. Sends are counted one
//!   at a time under an exclusive lock on one settings row, so concurrent requests cannot share the last message of a
//!   day or the same interval (the first code for a number has no row of its own to lock). Once the site-wide daily
//!   amount is reached an operation log row is written, and the admin "Login methods" page shows a prominent notice.
//! - A new code only becomes current once the provider took it: its row is written as not delivered
//!   (`expires_at = dateline`) and given its lifetime after delivery, so a send that fails or is interrupted leaves
//!   the code the member already has working.
//! - Read-only mode leaves signing in and account security open, so their codes are still sent; only a sign-in code
//!   for a number without an account is held back, as it could only lead to signing up.
//! - Lock order: settings gate, send lock, then code row, then member row.
use crate::db::Tx;
use hmac::{Hmac, Mac};
use rand::Rng as _;

use super::*;

/// How long the "Enter the code" step remembers the number after a code is sent.
pub const STEP_TTL: i64 = 1800;
/// How long a number that passed SMS verification but has not finished registration stays in the encrypted cookie.
pub const REGISTRATION_TTL: i64 = 1800;
const STEP_AAD: &[u8] = b"gonof.sms-step.v1";
const REGISTRATION_AAD: &[u8] = b"gonof.sms-registration.v1";
const CODE_DIGITS: usize = 6;
/// Label of the code digest key derived from the cookie keys ([`cookie::CookieConfig::derived_keys`]).
const CODE_KEY_LABEL: &[u8] = b"gonof.sms-code.v1";
/// The send lock: an existing settings row outside the settings gate (which every send holds shared), taken
/// exclusively the way one-at-a-time admin saves take it. Nothing else holds it per request, so sends wait only for
/// each other and for those saves.
const SEND_LOCK_SQL: &str =
    "SELECT skey FROM gonof_common_settings WHERE skey='identity.bootstrap_admin' FOR UPDATE";

pub(crate) const MOBILE_BIND_LOG: &str = "identity.mobile.bind";
pub(crate) const MOBILE_CHANGE_LOG: &str = "identity.mobile.change";
pub(crate) const MOBILE_UNBIND_LOG: &str = "identity.mobile.unbind";
pub(crate) const PASSWORD_SET_LOG: &str = "identity.password.set";
/// The operation log written when the site-wide daily sending amount reaches the limit (one per day).
pub const SITE_LIMIT_LOG: &str = "sms.site_daily_limit";

/// The purpose of a verification code.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum SmsPurpose {
    /// SMS login and registration.
    Login,
    /// Binding or rebinding a mobile number (sent to the new number).
    Bind,
    /// Confirming identity before an account without a password sets one (sent to the bound number).
    Confirm,
}

impl SmsPurpose {
    pub fn value(self) -> &'static str {
        match self {
            Self::Login => "login",
            Self::Bind => "bind",
            Self::Confirm => "confirm",
        }
    }
}

/// Normalises to E.164: strips spaces and hyphens, accepts the `+86`, `86` and `0086` prefixes; requires 11 digits,
/// starting with 1, with a second digit of 3–9.
pub fn normalize_mobile(value: &str) -> Result<String> {
    let compact: String = value
        .trim()
        .chars()
        .filter(|ch| !matches!(ch, ' ' | '-' | '\u{3000}'))
        .collect();
    let digits = compact
        .strip_prefix("+86")
        .or_else(|| compact.strip_prefix("0086"))
        .or_else(|| compact.strip_prefix("86").filter(|rest| rest.len() == 11))
        .unwrap_or(&compact);
    let bytes = digits.as_bytes();
    if bytes.len() == 11
        && bytes.iter().all(u8::is_ascii_digit)
        && bytes[0] == b'1'
        && (b'3'..=b'9').contains(&bytes[1])
    {
        Ok(format!("+86{digits}"))
    } else {
        Err(IdentityError::Validation(
            crate::i18n::current().account_error_mobile_invalid(),
        ))
    }
}

/// Masked display: `+8613812345678` → `138****5678`.
pub fn mask_mobile(mobile: &str) -> String {
    let digits = mobile.strip_prefix("+86").unwrap_or(mobile);
    if digits.len() == 11 && digits.is_ascii() {
        format!("{}****{}", &digits[..3], &digits[7..])
    } else {
        "***".into()
    }
}

/// Why sending a code failed.
#[derive(Debug)]
pub enum SmsSendError {
    /// Seconds to wait before sending to this number again.
    Wait(i64),
    /// This number's messages for today are used up.
    MobileDaily,
    /// The site-wide messages for today are used up.
    SiteDaily,
    /// The number is invalid, or the provider is throttling: tell the member as is.
    Rejected(&'static str),
    Identity(IdentityError),
}

impl From<IdentityError> for SmsSendError {
    fn from(error: IdentityError) -> Self {
        Self::Identity(error)
    }
}

impl From<sqlx::Error> for SmsSendError {
    fn from(error: sqlx::Error) -> Self {
        Self::Identity(error.into())
    }
}

impl From<anyhow::Error> for SmsSendError {
    fn from(error: anyhow::Error) -> Self {
        Self::Identity(error.into())
    }
}

/// The "Enter the code" step after sending a code: number and purpose (encrypted cookie). `uid` is the member who
/// started it, 0 for SMS login.
#[derive(Debug, Serialize, Deserialize)]
pub struct SmsStep {
    pub uid: i64,
    pub mobile: String,
    pub purpose: SmsPurpose,
    pub expires_at: i64,
}

#[derive(Serialize, Deserialize)]
struct RegistrationClaims {
    mobile: String,
    expires_at: i64,
}

/// Result of SMS login: a registered number logs in (or moves on to two-factor authentication); an unregistered number
/// goes on to finish registration, carrying encrypted pending-registration credentials.
pub enum SmsLoginOutcome {
    Login(LoginOutcome),
    Register(String),
}

enum CodeCheck {
    Valid,
    Wrong,
    Expired,
}

/// The stored digest of a code: 64 hex digits, like the plain SHA-256 used before, so the column is unchanged; rows
/// written in the old form simply no longer verify.
fn code_hash(
    key: &[u8; 32],
    mobile: &str,
    purpose: SmsPurpose,
    dateline: i64,
    code: &str,
) -> String {
    let mut mac = <Hmac<Sha256> as Mac>::new_from_slice(key).expect("HMAC accepts any key length");
    mac.update(format!("sms:{mobile}:{}:{dateline}:{code}", purpose.value()).as_bytes());
    hex(&mac.finalize().into_bytes())
}

fn generate_code() -> String {
    format!("{:06}", OsRng.gen_range(0..1_000_000))
}

impl Identity {
    /// Keys of the code digests, current first.
    fn code_keys(&self) -> Result<Vec<[u8; 32]>> {
        self.config
            .cookie
            .derived_keys(CODE_KEY_LABEL)
            .map_err(IdentityError::Internal)
    }

    pub fn seal_sms_step(&self, uid: i64, mobile: &str, purpose: SmsPurpose) -> Result<String> {
        self.config
            .cookie
            .seal_value(
                STEP_AAD,
                &SmsStep {
                    uid,
                    mobile: mobile.to_owned(),
                    purpose,
                    expires_at: now() + STEP_TTL,
                },
            )
            .map_err(IdentityError::Internal)
    }

    /// Reads the "Enter the code" step; a mismatched purpose or initiator, or expiry, is treated as absent.
    pub fn open_sms_step(&self, raw: &str, uid: i64, purpose: SmsPurpose) -> Option<SmsStep> {
        let timestamp = now();
        self.config
            .cookie
            .open_value::<SmsStep>(STEP_AAD, raw)
            .filter(|step| {
                step.uid == uid
                    && step.purpose == purpose
                    && step.expires_at > timestamp
                    && step.expires_at <= timestamp + STEP_TTL
                    && normalize_mobile(&step.mobile).ok().as_deref() == Some(step.mobile.as_str())
            })
    }

    /// The number in the pending-registration credentials; `None` when expired or undecryptable.
    pub fn registration_mobile(&self, raw: &str) -> Option<String> {
        let timestamp = now();
        self.config
            .cookie
            .open_value::<RegistrationClaims>(REGISTRATION_AAD, raw)
            .filter(|claims| {
                claims.expires_at > timestamp && claims.expires_at <= timestamp + REGISTRATION_TTL
            })
            .map(|claims| claims.mobile)
    }

    /// Sends a verification code. The number must be normalised first; `client_ip` is only recorded on the code row.
    pub async fn send_sms_code(
        &self,
        mobile: &str,
        purpose: SmsPurpose,
        client_ip: &str,
    ) -> std::result::Result<(), SmsSendError> {
        let mobile = normalize_mobile(mobile)?;
        let timestamp = now();
        // READ COMMITTED on MySQL: every count below sees the sends committed while this one waited for the lock.
        let mut tx = self.db.begin_content_write().await?;
        let settings = crate::runtime::locked(&self.db, &mut tx).await?;
        let sms = &settings.sms;
        crate::db::query(SEND_LOCK_SQL)
            .fetch_one(self.db.observe(&mut *tx))
            .await?;
        if settings.site.read_only && purpose == SmsPurpose::Login {
            let bound: Option<i64> =
                crate::db::query_scalar("SELECT uid FROM gonof_common_member WHERE mobile=?")
                    .bind(&mobile)
                    .fetch_optional(self.db.observe(&mut *tx))
                    .await?;
            if bound.is_none() {
                return Err(SmsSendError::Identity(IdentityError::Suspended(
                    settings.site.read_only_notice(crate::i18n::current()),
                )));
            }
        }
        let last: Option<i64> = crate::db::query_scalar(
            "SELECT dateline FROM gonof_common_sms_code WHERE mobile=? ORDER BY dateline DESC LIMIT 1",
        )
        .bind(&mobile)
        .fetch_optional(self.db.observe(&mut *tx))
        .await?;
        if let Some(last) = last {
            let ready = last.saturating_add(sms.mobile_interval_seconds);
            if timestamp < ready {
                return Err(SmsSendError::Wait(ready - timestamp));
            }
        }
        let day = crate::clock::day_start(timestamp, settings.time.offset_minutes);
        // "Today's Nth message" fetches the Nth row by index, so the rows read are bounded by the limit.
        let mobile_full: Option<i64> = crate::db::query_scalar(
            "SELECT id FROM gonof_common_sms_code WHERE mobile=? AND dateline>=? ORDER BY dateline LIMIT 1 OFFSET ?",
        )
        .bind(&mobile)
        .bind(day)
        .bind(sms.mobile_daily_limit - 1)
        .fetch_optional(self.db.observe(&mut *tx))
        .await?;
        if mobile_full.is_some() {
            return Err(SmsSendError::MobileDaily);
        }
        let site_full: Option<i64> = crate::db::query_scalar(
            "SELECT id FROM gonof_common_sms_code WHERE dateline>=? ORDER BY dateline LIMIT 1 OFFSET ?",
        )
        .bind(day)
        .bind(sms.site_daily_limit - 1)
        .fetch_optional(self.db.observe(&mut *tx))
        .await?;
        if site_full.is_some() {
            let logged: Option<i64> = crate::db::query_scalar(
                "SELECT id FROM gonof_common_log WHERE type=? AND dateline>=? LIMIT 1",
            )
            .bind(SITE_LIMIT_LOG)
            .bind(day)
            .fetch_optional(self.db.observe(&mut *tx))
            .await?;
            if logged.is_none() {
                tracing::warn!(
                    limit = sms.site_daily_limit,
                    "the site-wide SMS volume for today has reached the limit; further codes will not be sent"
                );
                crate::db::query("INSERT INTO gonof_common_log(uid,operationuid,type,data,source,dateline) VALUES(NULL,NULL,?,?,'web',?)")
                    .bind(SITE_LIMIT_LOG)
                    .bind(serde_json::json!({"limit": sms.site_daily_limit, "day_start": day}).to_string())
                    .bind(timestamp)
                    .execute(self.db.observe(&mut *tx))
                    .await?;
                tx.commit().await?;
            }
            return Err(SmsSendError::SiteDaily);
        }
        let code = generate_code();
        let digest = code_hash(&self.code_keys()?[0], &mobile, purpose, timestamp, &code);
        let expires_at = timestamp + sms.code_ttl_minutes.saturating_mul(60);
        // Written as not delivered: it counts for the interval and the daily limits at once, and becomes the current
        // code only after the provider took it.
        let id = crate::db::query("INSERT INTO gonof_common_sms_code(mobile,purpose,code_hash,dateline,expires_at,client_ip) VALUES(?,?,?,?,?,?)")
            .bind(&mobile)
            .bind(purpose.value())
            .bind(digest)
            .bind(timestamp)
            .bind(timestamp)
            .bind(client_ip.chars().take(45).collect::<String>())
            .execute(self.db.observe(&mut *tx))
            .await?
            .last_insert_id();
        tx.commit().await?;
        let message = crate::sms::Message {
            id: i64::try_from(id).context("code id out of range")?,
            mobile: &mobile,
            code: &code,
            ttl_minutes: sms.code_ttl_minutes,
            purpose: purpose.value(),
        };
        let delivered =
            crate::sms::deliver(&self.db, &self.common, &self.private_directory(), &message).await;
        match delivered {
            Ok(()) => {
                // A code that did not go out (or whose send stopped half way) never gets here: with no lifetime
                // `check_code` passes over its row, and the code the member received before still works.
                crate::db::query(
                    "UPDATE gonof_common_sms_code SET expires_at=? WHERE id=? AND expires_at=dateline",
                )
                .bind(expires_at)
                .bind(message.id)
                .execute(self.db.executor())
                .await?;
                Ok(())
            }
            Err(crate::sms::DeliveryError::Frequent) => Err(SmsSendError::Rejected(
                crate::i18n::current().account_error_sms_frequent(),
            )),
            Err(crate::sms::DeliveryError::InvalidNumber) => Err(SmsSendError::Rejected(
                crate::i18n::current().account_error_mobile_invalid(),
            )),
            Err(crate::sms::DeliveryError::Failed(error)) => {
                tracing::warn!(error = %error, "failed to send SMS verification code");
                Err(SmsSendError::Rejected(
                    crate::i18n::current().account_error_sms_failed(),
                ))
            }
        }
    }

    /// Verifies and consumes a code. The caller has a write transaction open; on `Wrong` the caller must commit
    /// (recording this wrong attempt) and then report the error.
    async fn check_code(
        &self,
        tx: &mut Tx<'_>,
        mobile: &str,
        purpose: SmsPurpose,
        input: &str,
        max_attempts: i64,
        timestamp: i64,
    ) -> Result<CodeCheck> {
        // The latest code that was delivered: a row not (yet) delivered has `expires_at = dateline`
        // (`send_sms_code`; a delivered code lives at least a minute).
        let row = crate::db::query(
            "SELECT id,code_hash,dateline,expires_at,attempts,consumed_at FROM gonof_common_sms_code
             WHERE mobile=? AND purpose=? AND expires_at>dateline ORDER BY dateline DESC, id DESC LIMIT 1 FOR UPDATE",
        )
        .bind(mobile)
        .bind(purpose.value())
        .fetch_optional(self.db.observe(&mut **tx))
        .await?;
        let Some(row) = row else {
            return Ok(CodeCheck::Expired);
        };
        let id: i64 = row.try_get("id")?;
        let attempts: i64 = row.try_get("attempts")?;
        let consumed: Option<i64> = row.try_get("consumed_at")?;
        let dateline: i64 = row.try_get("dateline")?;
        if consumed.is_some()
            || row.try_get::<i64, _>("expires_at")? <= timestamp
            || attempts >= max_attempts
        {
            return Ok(CodeCheck::Expired);
        }
        let input = input.trim();
        let expected = db::text(&row, "code_hash")?;
        let shaped = input.len() == CODE_DIGITS && input.bytes().all(|b| b.is_ascii_digit());
        let matches = shaped
            && self.code_keys()?.iter().any(|key| {
                bool::from(
                    code_hash(key, mobile, purpose, dateline, input)
                        .as_bytes()
                        .ct_eq(expected.as_bytes()),
                )
            });
        if !matches {
            crate::db::query(
                "UPDATE gonof_common_sms_code SET attempts=attempts+1 WHERE id=? AND attempts=?",
            )
            .bind(id)
            .bind(attempts)
            .execute(self.db.observe(&mut **tx))
            .await?;
            return Ok(CodeCheck::Wrong);
        }
        let used = crate::db::query("UPDATE gonof_common_sms_code SET consumed_at=GREATEST(dateline,?) WHERE id=? AND consumed_at IS NULL")
            .bind(timestamp)
            .bind(id)
            .execute(self.db.observe(&mut **tx))
            .await?
            .rows_affected();
        Ok(if used == 1 {
            CodeCheck::Valid
        } else {
            CodeCheck::Expired
        })
    }

    /// Verifies inside the open transaction; on a wrong code commits this count and reports the error. The caller reads
    /// the wrong-attempt limit before opening the transaction.
    async fn require_code(
        &self,
        mut tx: Tx<'static>,
        mobile: &str,
        purpose: SmsPurpose,
        input: &str,
        timestamp: i64,
        max_attempts: i64,
    ) -> Result<Tx<'static>> {
        match self
            .check_code(&mut tx, mobile, purpose, input, max_attempts, timestamp)
            .await?
        {
            CodeCheck::Valid => Ok(tx),
            CodeCheck::Wrong => {
                tx.commit().await?;
                Err(IdentityError::Validation(
                    crate::i18n::current().account_error_wrong_code(),
                ))
            }
            CodeCheck::Expired => Err(IdentityError::Validation(
                crate::i18n::current().account_error_expired_code(),
            )),
        }
    }

    /// SMS login: a bound number logs in (moving on to the second step when two-factor authentication is on and the
    /// admin setting requires it); an unbound number gets pending-registration credentials.
    pub async fn sms_login(
        &self,
        mobile: &str,
        code: &str,
        metadata: &SessionMetadata,
    ) -> Result<SmsLoginOutcome> {
        let mobile = normalize_mobile(mobile)?;
        let settings = self.settings().await?;
        let timestamp = now();
        let tx = self.db.begin_write().await?;
        let mut tx = self
            .require_code(
                tx,
                &mobile,
                SmsPurpose::Login,
                code,
                timestamp,
                settings.sms.max_attempts,
            )
            .await?;
        let uid: Option<i64> =
            crate::db::query_scalar("SELECT uid FROM gonof_common_member WHERE mobile=?")
                .bind(&mobile)
                .fetch_optional(self.db.observe(&mut *tx))
                .await?;
        let Some(uid) = uid else {
            if settings.site.read_only {
                return Err(IdentityError::Suspended(
                    settings.site.read_only_notice(crate::i18n::current()),
                ));
            }
            if settings.signup.mode == "closed" {
                return Err(IdentityError::Conflict(
                    crate::i18n::current().account_error_mobile_closed(),
                ));
            }
            tx.commit().await?;
            let token = self
                .config
                .cookie
                .seal_value(
                    REGISTRATION_AAD,
                    &RegistrationClaims {
                        mobile,
                        expires_at: timestamp + REGISTRATION_TTL,
                    },
                )
                .map_err(IdentityError::Internal)?;
            return Ok(SmsLoginOutcome::Register(token));
        };
        let member = self.member_locked(&mut tx, uid).await?;
        if member.mobile.as_deref() != Some(mobile.as_str()) {
            return Err(IdentityError::Unauthorized);
        }
        if !member.active() || member.frozen {
            if let Some(message) = crate::moderation::frozen_notice(&self.db, &mut tx, uid).await? {
                return Err(IdentityError::Suspended(message));
            }
            return Err(IdentityError::Unauthorized);
        }
        if settings.login.external_two_factor == "require"
            && self.has_two_factor_locked(&mut tx, uid).await?
        {
            tx.commit().await?;
            return Ok(SmsLoginOutcome::Login(LoginOutcome::SecondFactor(
                self.pending_login(&member, timestamp)?,
            )));
        }
        let grant = self
            .finish_login(
                &mut tx,
                member,
                metadata,
                Some("sms"),
                None,
                timestamp,
                &settings.account,
            )
            .await?;
        tx.commit().await?;
        Ok(SmsLoginOutcome::Login(LoginOutcome::Session(Box::new(
            grant,
        ))))
    }

    /// Completes registration for an SMS-verified number: choose a username, optionally give an email (which goes
    /// through the usual verification flow), and enter an invite code under invite-only registration. No password is
    /// set.
    pub async fn register_with_mobile(
        &self,
        token: &str,
        username: &str,
        email: &str,
        invite_code: &str,
        metadata: &SessionMetadata,
        consent: Option<PolicyConsent>,
    ) -> Result<SessionGrant> {
        let mobile = self
            .registration_mobile(token)
            .ok_or(IdentityError::Validation(
                crate::i18n::current().account_error_mobile_expired(),
            ))?;
        let username = normalize_username(username)?;
        let email = if email.trim().is_empty() {
            None
        } else {
            Some(normalize_email(email)?)
        };
        let invite_code = invite_code.trim();
        if invite_code.len() > 64 {
            return Err(IdentityError::Validation(
                crate::i18n::current().account_error_invite_invalid(),
            ));
        }
        registration_open(&*self.settings().await?, invite_code)?;
        self.create_account(NewAccount {
            username,
            email,
            email_verified: false,
            password: None,
            mobile: Some(mobile),
            external: None,
            invite_code,
            metadata,
            consent,
            method: "sms",
        })
        .await
    }

    /// Saves the SMS provider configuration from the admin area (the secret is encrypted with the private config
    /// `[common] encryption_key`).
    pub async fn save_sms_provider(
        &self,
        actor: Actor,
        input: crate::sms::SmsInput,
    ) -> Result<crate::sms::Providers> {
        crate::sms::save_sms(&self.db, &self.common, actor, input).await
    }

    /// Whether the private config `[common] encryption_key` is set (for the admin-area notice).
    pub fn providers_key_configured(&self) -> bool {
        self.common.configured()
    }

    /// Number of verification codes sent site-wide today (shown on the admin "Login methods" page). Rows read do not
    /// exceed today's sending volume.
    pub async fn sms_sent_today(&self) -> Result<i64> {
        let settings = self.settings().await?;
        let day = crate::clock::day_start(now(), settings.time.offset_minutes);
        Ok(
            crate::db::query_scalar("SELECT COUNT(*) FROM gonof_common_sms_code WHERE dateline>=?")
                .bind(day)
                .fetch_one(self.db.executor())
                .await?,
        )
    }

    /// Sets a password for an account without one: first confirm identity with a code sent to the bound number.
    /// Afterwards the credentials version is incremented and all devices are logged out, consistent with changing the
    /// password.
    pub async fn set_password_with_sms(
        &self,
        raw_cookie: &str,
        code: &str,
        new_password: &str,
    ) -> Result<()> {
        let settings = self.settings().await?;
        validate_password(new_password, settings.account.password_min_length)?;
        let claims = self.cookie_claims(raw_cookie)?;
        let mobile: Option<String> =
            crate::db::query_scalar("SELECT mobile FROM gonof_common_member WHERE uid=?")
                .bind(claims.uid)
                .fetch_optional(self.db.executor())
                .await?
                .flatten();
        let mobile = mobile.ok_or(IdentityError::Validation(
            crate::i18n::current().account_error_mobile_first(),
        ))?;
        let encoded = hash_password(new_password.to_owned()).await?;
        let timestamp = now();
        let tx = self.db.begin_write().await?;
        let mut tx = self
            .require_code(
                tx,
                &mobile,
                SmsPurpose::Confirm,
                code,
                timestamp,
                settings.sms.max_attempts,
            )
            .await?;
        let LockedAccount { member, password } =
            self.security_account_locked(&mut tx, raw_cookie).await?;
        if password.is_some() {
            return Err(IdentityError::Conflict(
                crate::i18n::current().account_error_password_exists(),
            ));
        }
        if member.mobile.as_deref() != Some(mobile.as_str()) {
            return Err(IdentityError::Unauthorized);
        }
        rules::Credentials {
            password: Some(&encoded),
            email: member.email.as_deref(),
            mobile: member.mobile.as_deref(),
            // There is a mobile number, so external account bindings do not affect the result.
            external: false,
            emailstatus: i64::from(member.email_verified),
            adminid: member.adminid,
        }
        .check()?;
        let log_id = self
            .replace_password(&mut tx, &member, &encoded, timestamp, PASSWORD_SET_LOG)
            .await?;
        two_factor::enqueue_notice(&self.db, &mut tx, &member, log_id, timestamp).await?;
        tx.commit().await?;
        Ok(())
    }

    /// Whether the account has a password (the account security page decides whether to show "Change password" or
    /// "Set a password").
    pub async fn has_password(&self, uid: i64) -> Result<bool> {
        let password: Option<Option<String>> =
            crate::db::query_scalar("SELECT password FROM gonof_common_member WHERE uid=?")
                .bind(uid)
                .fetch_optional(self.db.executor())
                .await?;
        Ok(password.flatten().is_some_and(|value| !value.is_empty()))
    }

    /// Binds or rebinds a mobile number: requires the current password (an account without a password sets one first)
    /// and a code sent to the new number.
    pub async fn bind_mobile(
        &self,
        raw_cookie: &str,
        current_password: &str,
        mobile: &str,
        code: &str,
    ) -> Result<()> {
        let mobile = normalize_mobile(mobile)?;
        let verified = self
            .verified_for_mobile(raw_cookie, current_password)
            .await?;
        let max_attempts = self.settings().await?.sms.max_attempts;
        let timestamp = now();
        let tx = self.db.begin_write().await?;
        let mut tx = self
            .require_code(tx, &mobile, SmsPurpose::Bind, code, timestamp, max_attempts)
            .await?;
        let LockedAccount { member, password } =
            self.security_account_locked(&mut tx, raw_cookie).await?;
        if member.credentials_version != verified.claims.credentials_version
            || password != verified.previous
        {
            return Err(IdentityError::Unauthorized);
        }
        if member.email_unverified() {
            return Err(external::verify_email_first());
        }
        if member.mobile.as_deref() == Some(mobile.as_str()) {
            return Err(IdentityError::Conflict(
                crate::i18n::current().account_error_mobile_linked_here(),
            ));
        }
        let taken: Option<i64> = crate::db::query_scalar(
            "SELECT uid FROM gonof_common_member WHERE mobile=? FOR UPDATE",
        )
        .bind(&mobile)
        .fetch_optional(self.db.observe(&mut *tx))
        .await?;
        if taken.is_some() {
            return Err(IdentityError::Conflict(
                crate::i18n::current().account_error_mobile_taken(),
            ));
        }
        rules::Credentials {
            password: password.as_deref(),
            email: member.email.as_deref(),
            mobile: Some(&mobile),
            // There is a mobile number, so external account bindings do not affect the result.
            external: false,
            emailstatus: i64::from(member.email_verified),
            adminid: member.adminid,
        }
        .check()?;
        let changed = crate::db::query(
            "UPDATE gonof_common_member SET mobile=? WHERE uid=? AND credentials_version=?",
        )
        .bind(&mobile)
        .bind(member.uid)
        .bind(member.credentials_version)
        .execute(self.db.observe(&mut *tx))
        .await?
        .rows_affected();
        if changed != 1 {
            return Err(IdentityError::Unauthorized);
        }
        let (operation, data) = match &member.mobile {
            Some(previous) => (
                MOBILE_CHANGE_LOG,
                serde_json::json!({"mobile": mask_mobile(&mobile), "from": mask_mobile(previous)}),
            ),
            None => (
                MOBILE_BIND_LOG,
                serde_json::json!({"mobile": mask_mobile(&mobile)}),
            ),
        };
        let log_id = self
            .audit(&mut tx, member.uid, operation, data, timestamp)
            .await?;
        two_factor::enqueue_notice(&self.db, &mut tx, &member, log_id, timestamp).await?;
        tx.commit().await?;
        Ok(())
    }

    /// Unbinds the mobile number: requires the current password; an account with neither an email nor an external
    /// binding cannot unbind (afterwards it could neither log in by SMS nor recover its password).
    pub async fn unbind_mobile(&self, raw_cookie: &str, current_password: &str) -> Result<()> {
        let verified = self
            .verified_for_mobile(raw_cookie, current_password)
            .await?;
        let timestamp = now();
        let mut tx = self.db.begin_write().await?;
        let LockedAccount { member, password } =
            self.security_account_locked(&mut tx, raw_cookie).await?;
        if member.credentials_version != verified.claims.credentials_version
            || password != verified.previous
        {
            return Err(IdentityError::Unauthorized);
        }
        let Some(previous) = member.mobile.clone() else {
            return Err(IdentityError::Conflict(
                crate::i18n::current().account_error_mobile_none(),
            ));
        };
        // The member row is locked, so this is serialised with external account binding and unbinding.
        let linked = crate::login::linked(self.db.observe(&mut *tx), member.uid).await?;
        let allowed = rules::Credentials {
            password: password.as_deref(),
            email: member.email.as_deref(),
            mobile: None,
            external: linked.google || linked.github,
            emailstatus: i64::from(member.email_verified),
            adminid: member.adminid,
        }
        .check()
        .is_ok();
        if !allowed {
            return Err(IdentityError::Conflict(
                crate::i18n::current().account_error_mobile_unbind_last(),
            ));
        }
        crate::db::query(
            "UPDATE gonof_common_member SET mobile=NULL WHERE uid=? AND credentials_version=?",
        )
        .bind(member.uid)
        .bind(member.credentials_version)
        .execute(self.db.observe(&mut *tx))
        .await?;
        let log_id = self
            .audit(
                &mut tx,
                member.uid,
                MOBILE_UNBIND_LOG,
                serde_json::json!({"mobile": mask_mobile(&previous)}),
                timestamp,
            )
            .await?;
        two_factor::enqueue_notice(&self.db, &mut tx, &member, log_id, timestamp).await?;
        tx.commit().await?;
        Ok(())
    }

    /// Password recovery claims an account whose email was never verified ([`Identity::reset_password`]): a phone
    /// number bound before then goes with it, since whoever knew the password may have bound their own number to sign
    /// in by text message. Logged like an unbind, with the cause. The caller holds the member row lock.
    pub(super) async fn remove_mobile_on_claim(
        &self,
        tx: &mut Tx<'_>,
        member: &Member,
        cause: &str,
        timestamp: i64,
    ) -> Result<()> {
        let Some(previous) = member.mobile.as_deref() else {
            return Ok(());
        };
        crate::db::query("UPDATE gonof_common_member SET mobile=NULL WHERE uid=?")
            .bind(member.uid)
            .execute(self.db.observe(&mut **tx))
            .await?;
        self.audit(
            tx,
            member.uid,
            MOBILE_UNBIND_LOG,
            serde_json::json!({"mobile": mask_mobile(previous), "cause": cause}),
            timestamp,
        )
        .await?;
        Ok(())
    }

    /// Checks the current password before binding or unbinding; an account without a password must set one first.
    async fn verified_for_mobile<'a>(
        &self,
        raw_cookie: &'a str,
        current_password: &str,
    ) -> Result<VerifiedPassword<'a>> {
        // Without a password, reports `account-error-no-password` (set a password first).
        self.check_current_password(raw_cookie, current_password)
            .await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mobiles_normalize_to_e164_and_mask() {
        for input in [
            "13812345678",
            "138 1234 5678",
            "138-1234-5678",
            "+8613812345678",
            "+86 138 1234 5678",
            "8613812345678",
            "008613812345678",
        ] {
            assert_eq!(
                normalize_mobile(input).unwrap(),
                "+8613812345678",
                "{input}"
            );
        }
        for bad in [
            "",
            "1381234567",
            "138123456789",
            "12812345678",
            "23812345678",
            "+12025550123",
            "1381234567a",
            // Full-width digits (U+FF10 to U+FF19) are not accepted as a number.
            "\u{ff11}\u{ff13}\u{ff18}\u{ff11}\u{ff12}\u{ff13}\u{ff14}\u{ff15}\u{ff16}\u{ff17}\u{ff18}",
        ] {
            assert!(normalize_mobile(bad).is_err(), "{bad}");
        }
        assert_eq!(mask_mobile("+8613812345678"), "138****5678");
    }

    /// A code that could not be sent does not replace the one already delivered: that one still verifies, and the
    /// failed attempt still counts for the interval.
    #[tokio::test]
    async fn an_unsent_code_leaves_the_delivered_one_current() {
        let services = crate::test_support::TestFixture::migrated().await.unwrap();
        let identity = Identity::new(
            services.db.clone(),
            services.config.identity.clone(),
            services.root.clone(),
            crate::test_support::detached_global(),
        );
        let mobile = "+8613800138000";
        let issued = now() - 120;
        crate::db::query("INSERT INTO gonof_common_sms_code(mobile,purpose,code_hash,dateline,expires_at) VALUES(?,?,?,?,?)")
            .bind(mobile)
            .bind(SmsPurpose::Login.value())
            .bind(code_hash(
                &identity.code_keys().unwrap()[0],
                mobile,
                SmsPurpose::Login,
                issued,
                "246810",
            ))
            .bind(issued)
            .bind(issued + 600)
            .execute(services.db.executor())
            .await
            .unwrap();
        // Local delivery fails while a file stands where its directory belongs.
        std::fs::create_dir_all(identity.private_directory()).unwrap();
        std::fs::write(identity.private_directory().join("sms"), "").unwrap();
        let send = || identity.send_sms_code(mobile, SmsPurpose::Login, "192.0.2.1");
        assert!(matches!(send().await, Err(SmsSendError::Rejected(_))));
        assert!(matches!(send().await, Err(SmsSendError::Wait(_))));
        let mut tx = services.db.begin_write().await.unwrap();
        let checked = identity
            .check_code(&mut tx, mobile, SmsPurpose::Login, "246810", 5, now())
            .await
            .unwrap();
        tx.commit().await.unwrap();
        assert!(matches!(checked, CodeCheck::Valid));
        services.cleanup().await.unwrap();
    }

    #[test]
    fn code_hash_binds_key_number_purpose_and_time() {
        let key = [7; 32];
        let base = code_hash(&key, "+8613812345678", SmsPurpose::Login, 100, "123456");
        assert_eq!(base.len(), 64);
        assert_ne!(
            base,
            code_hash(&key, "+8613812345679", SmsPurpose::Login, 100, "123456")
        );
        assert_ne!(
            base,
            code_hash(&key, "+8613812345678", SmsPurpose::Bind, 100, "123456")
        );
        assert_ne!(
            base,
            code_hash(&key, "+8613812345678", SmsPurpose::Login, 101, "123456")
        );
        assert_ne!(
            base,
            code_hash(&[8; 32], "+8613812345678", SmsPurpose::Login, 100, "123456"),
            "the digest depends on the key"
        );
        assert_ne!(
            base,
            token_hash("sms:+8613812345678:login:100:123456"),
            "the digest is not the old unkeyed SHA-256"
        );
        let code = generate_code();
        assert_eq!(code.len(), 6);
        assert!(code.bytes().all(|b| b.is_ascii_digit()));
    }

    /// The digest key comes from the cookie keys: a code sent before a rotation still verifies while the old cookie
    /// key is in `previous_keys` and no longer once it is removed; a row in the old unkeyed form no longer verifies.
    #[tokio::test]
    async fn code_digests_follow_the_cookie_keys() {
        let services = crate::test_support::TestFixture::migrated().await.unwrap();
        let with_keys = |active: &str, previous: &[&str]| {
            let mut config = services.config.identity.clone();
            config.cookie.active_key = active.to_owned();
            config.cookie.previous_keys = previous.iter().map(|key| (*key).to_owned()).collect();
            Identity::new(
                services.db.clone(),
                config,
                services.root.clone(),
                crate::test_support::detached_global(),
            )
        };
        let (old, new) = ("21".repeat(32), "43".repeat(32));
        let before = with_keys(&old, &[]);
        let rotated = with_keys(&new, &[&old]);
        let replaced = with_keys(&new, &[]);
        assert_eq!(
            before.code_keys().unwrap()[0],
            rotated.code_keys().unwrap()[1]
        );
        assert_ne!(
            before.code_keys().unwrap()[0].as_slice(),
            hex_bytes(&old).as_slice(),
            "the digest key is derived, not the cookie key itself"
        );
        let issued = now() - 60;
        let insert = |mobile: &'static str, digest: String| {
            let db = services.db.clone();
            async move {
                crate::db::query("INSERT INTO gonof_common_sms_code(mobile,purpose,code_hash,dateline,expires_at) VALUES(?,?,?,?,?)")
                    .bind(mobile)
                    .bind(SmsPurpose::Login.value())
                    .bind(digest)
                    .bind(issued)
                    .bind(issued + 600)
                    .execute(db.executor())
                    .await
                    .unwrap();
            }
        };
        let check = |identity: &Identity, mobile: &'static str| {
            let identity = identity.clone();
            let db = services.db.clone();
            async move {
                let mut tx = db.begin_write().await.unwrap();
                let checked = identity
                    .check_code(&mut tx, mobile, SmsPurpose::Login, "135790", 5, now())
                    .await
                    .unwrap();
                tx.commit().await.unwrap();
                checked
            }
        };
        let rotating = "+8613800138001";
        let key = before.code_keys().unwrap()[0];
        insert(
            rotating,
            code_hash(&key, rotating, SmsPurpose::Login, issued, "135790"),
        )
        .await;
        assert!(matches!(check(&replaced, rotating).await, CodeCheck::Wrong));
        assert!(matches!(check(&rotated, rotating).await, CodeCheck::Valid));
        // Codes stored before the digest had a key: the inputs are all in the row, so these no longer verify.
        let legacy = "+8613800138002";
        insert(
            legacy,
            token_hash(&format!("sms:{legacy}:login:{issued}:135790")),
        )
        .await;
        assert!(matches!(check(&rotated, legacy).await, CodeCheck::Wrong));
        services.cleanup().await.unwrap();
    }

    fn hex_bytes(value: &str) -> Vec<u8> {
        (0..value.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&value[i..i + 2], 16).unwrap())
            .collect()
    }
}
